import React, { useEffect, useState } from 'react'
import useLayerStore from '../../../utils/store'
import { getAssetMeta } from '../../../utils/dataV2.js'
import { getPartPreviewHex } from '../../../utils/color-display'
import DarkBorder from '../../border-container/dark-border-container'
import {
  EyesContainer,
  PreviewContainer,
  TextContainer,
  LeftArrow,
  RightArrow,
  ColorPreview,
  ButtonContainer,
  InnerContainer,
} from './eyes.style'

const Eyes = () => {
  const addAssetLayer = useLayerStore((state) => state.addAssetLayer)
  const setSelectedLayer = useLayerStore((state) => state.setSelectedLayer)
  const setLayerPartSelection = useLayerStore((state) => state.setLayerPartSelection)
  const layerArr = useLayerStore((state) => state.layerArr)
  const updateLayer = useLayerStore((state) => state.updateLayer)
  const [hex, setHex] = useState('#393939')
  const eyeMeta = getAssetMeta('Physique', 'Etc_-_Eye_Color')
  const eyeParts = eyeMeta?.layers || []
  const eyeColorOptions = eyeParts[0]?.colorOptions || []

  const addEyeLayer = () => {
    const eyeLayerIndex = addAssetLayer('Physique', 'Etc_-_Eye_Color', false)
    if (eyeLayerIndex !== null) {
      setSelectedLayer(eyeLayerIndex)
      eyeParts.forEach((part) => {
        setLayerPartSelection(eyeLayerIndex, part.key, 'primary_Black.png')
      })
    }
  }

  const updateAllEyeParts = (currentLayer, selection) => ({
    ...currentLayer,
    parts: currentLayer.parts.map((part) => ({
      ...part,
      selection,
      tintHex: null,
      hueShift: 0,
      saturation: 0,
      lightness: 0,
      opacity: 100,
      contrast: 0,
    })),
  })

  const incrementEyeColor = () => {
    const eyeLayer = layerArr.find(
      (layer) => layer.assetName === 'Etc_-_Eye_Color'
    )
    if (eyeLayer) {
      const currentLayer = {
        ...eyeLayer,
        parts: eyeLayer.parts.map((part) => ({ ...part })),
      }
      const currentSelection = currentLayer.parts?.[0]?.selection
      const currentColorIndex = eyeColorOptions.findIndex(
        (color) => color === currentSelection
      )
      const nextSelection =
        currentColorIndex < eyeColorOptions.length - 1
          ? eyeColorOptions[currentColorIndex + 1]
          : eyeColorOptions[0]
      updateLayer(updateAllEyeParts(currentLayer, nextSelection))
    } else {
      addEyeLayer()
    }
  }

  const decrementEyeColor = () => {
    const eyeLayer = layerArr.find(
      (layer) => layer.assetName === 'Etc_-_Eye_Color'
    )
    if (eyeLayer) {
      const currentLayer = {
        ...eyeLayer,
        parts: eyeLayer.parts.map((part) => ({ ...part })),
      }
      const currentSelection = currentLayer.parts?.[0]?.selection
      const currentColorIndex = eyeColorOptions.findIndex(
        (color) => color === currentSelection
      )
      const nextSelection =
        currentColorIndex <= 0
          ? eyeColorOptions[eyeColorOptions.length - 1]
          : eyeColorOptions[currentColorIndex - 1]
      updateLayer(updateAllEyeParts(currentLayer, nextSelection))
    } else {
      addEyeLayer()
    }
  }

  useEffect(() => {
    const eyeLayer = layerArr.find((layer) => layer.assetName === 'Etc_-_Eye_Color')
    setHex(getPartPreviewHex(eyeLayer?.parts?.[0], '#393939'))
  }, [layerArr])

  return (
    <EyesContainer>
      <TextContainer className='font-face-gm'>Eyes</TextContainer>
      <ButtonContainer onClick={() => decrementEyeColor()}>
        <InnerContainer>
          <LeftArrow />
        </InnerContainer>
      </ButtonContainer>
      <PreviewContainer>
        <DarkBorder>
          <ColorPreview hex={hex} />
        </DarkBorder>
      </PreviewContainer>
      <ButtonContainer onClick={() => incrementEyeColor()}>
        <InnerContainer>
          <RightArrow />
        </InnerContainer>
      </ButtonContainer>
    </EyesContainer>
  )
}

export default Eyes
