import React, { useEffect, useState } from 'react'
import useLayerStore from '../../../utils/store'
import { getAssetPreviewPath, getLayerAssetMap } from '../../../utils/dataV2.js'
import PartColorSelector from './part-color-selector'
import BodyOptions from './body-options'
import ItemSelectModal from '../item-select-modal/item-select-modal'
import BorderContainer from '../../border-container/border-container'
import ItemSelect from './item-select'
import {
  ItemOptionsContainer,
  AssetContainer,
  AssetBorder,
  AssetPreview,
  AssetImage,
  LeftArrow,
  RightArrow,
  AssetSelectContainer,
  ButtonContainer,
  MobileContainer,
  ColorSelectorsGrid,
} from './item-options.style'
import { OptionsContainer } from '../options.style'
import Tooltip from '@mui/material/Tooltip'

const ItemOptions = () => {
  const [image, setImage] = useState()
  const [modalState, setModalState] = useState(false)
  const [selectionType, setSelectionType] = useState('')
  const { selectedLayer, layerArr, setAsset } = useLayerStore((state) => ({
    selectedLayer: state.selectedLayer,
    layerArr: state.layerArr,
    setAsset: state.setAsset,
  }))
  const currentLayer = layerArr[selectedLayer]

  useEffect(() => {
    if (!currentLayer) {
      setSelectionType('')
    }
  }, [currentLayer])

  useEffect(() => {
    if (!currentLayer || (currentLayer.layerType === 'Body' && currentLayer.isBaseLayer)) {
      return
    }
    setImage(getAssetPreviewPath(currentLayer.layerType, currentLayer.assetName))
  }, [currentLayer])

  if (!currentLayer) {
    return <></>
  }

  if (currentLayer.layerType === 'Body' && currentLayer.isBaseLayer) {
    return <BodyOptions />
  }

  const { layerType, assetName } = currentLayer
  const itemTypeOptions = Object.keys(getLayerAssetMap(layerType))
  const currentIndex = itemTypeOptions.indexOf(assetName)
  const isMobile = window.screen.width < 420

  const incrementAsset = () => {
    if (!itemTypeOptions.length) {
      return
    }

    const nextAsset =
      currentIndex === itemTypeOptions.length - 1
        ? itemTypeOptions[0]
        : itemTypeOptions[currentIndex + 1]
    setAsset(nextAsset)
  }

  const decrementAsset = () => {
    if (!itemTypeOptions.length) {
      return
    }

    const nextAsset =
      currentIndex <= 0
        ? itemTypeOptions[itemTypeOptions.length - 1]
        : itemTypeOptions[currentIndex - 1]
    setAsset(nextAsset)
  }

  return (
    <OptionsContainer>
      <BorderContainer>
        <MobileContainer>
          <ItemOptionsContainer>
            <AssetContainer>
              <ButtonContainer onClick={() => decrementAsset()}>
                <LeftArrow />
              </ButtonContainer>
              <Tooltip title={assetName.replaceAll('_', ' ')} arrow>
                <AssetBorder
                  onClick={
                    isMobile
                      ? () => setModalState(true)
                      : () => setSelectionType('asset')
                  }
                  isSelected={selectionType === 'asset'}
                >
                  <AssetPreview>
                    {image && <AssetImage importedImage={image} />}
                  </AssetPreview>
                </AssetBorder>
              </Tooltip>
              <ButtonContainer onClick={() => incrementAsset()}>
                <RightArrow />
              </ButtonContainer>
            </AssetContainer>
            <ColorSelectorsGrid>
              {currentLayer.parts.map((part) => (
                <PartColorSelector
                  key={`${currentLayer.id}-${part.key}`}
                  layerId={currentLayer.id}
                  layerType={currentLayer.layerType}
                  assetName={currentLayer.assetName}
                  part={part}
                  showLabel={currentLayer.parts.length > 1}
                />
              ))}
            </ColorSelectorsGrid>
            {!isMobile ? (
              <AssetSelectContainer>
                {selectionType === 'asset' && (
                  <ItemSelect
                    options={itemTypeOptions}
                    layerType={layerType}
                    itemType={assetName}
                  />
                )}
              </AssetSelectContainer>
            ) : (
              <ItemSelectModal
                open={modalState}
                onClose={() => setModalState(false)}
                options={itemTypeOptions}
                layerType={layerType}
              />
            )}
          </ItemOptionsContainer>
        </MobileContainer>
      </BorderContainer>
    </OptionsContainer>
  )
}

export default ItemOptions
