import React, { useEffect, useRef, useState } from 'react'
import mergeImages from 'merge-images'
import useLayerStore from '../../utils/store'
import colors from '../../utils/colors'
import {
  getAssetImagePath,
  getAssetPartMeta,
  isEmptyColorSelection,
} from '../../utils/dataV2'
import { normalizeAdjustments, processImageColor } from '../../utils/color-processing'

const colorHexByFileName = new Map(
  colors
    .filter((colorObject) => colorObject.hex)
    .map((colorObject) => [colorObject.fileName, colorObject.hex])
)

const getLayerPartImageSource = async (layer, part) => {
  if (isEmptyColorSelection(part.selection)) {
    return null
  }

  const partMeta = getAssetPartMeta(layer.layerType, layer.assetName, part.key)

  if (!partMeta) {
    return null
  }

  const sourceImage = getAssetImagePath(layer.layerType, layer.assetName, part.key)

  if (!sourceImage) {
    return null
  }

  const selectedColorHex = colorHexByFileName.get(part.selection) || null
  const adjustments = normalizeAdjustments({
    hueShift: part.hueShift,
    saturation: part.saturation,
    lightness: part.lightness,
    opacity: part.opacity,
    contrast: part.contrast,
  })
  const tintHex = part.tintHex || selectedColorHex

  if (
    !tintHex &&
    adjustments.hueShift === 0 &&
    adjustments.saturation === 0 &&
    adjustments.lightness === 0 &&
    adjustments.opacity === 100 &&
    adjustments.contrast === 0
  ) {
    return sourceImage
  }

  return processImageColor(sourceImage, tintHex, adjustments, {
    tintMode: partMeta.tintMode || 'luminance-map',
  })
}

const collectLayerImages = async (layer) => {
  if (!layer?.display) {
    return []
  }

  const layerImages = []

  for (const part of layer.parts || []) {
    const imageSource = await getLayerPartImageSource(layer, part)
    if (imageSource) {
      layerImages.push(imageSource)
    }
  }

  for (const additionalLayer of layer.additional || []) {
    const additionalImages = await collectLayerImages(additionalLayer)
    layerImages.push(...additionalImages)
  }

  return layerImages
}

const Canvas = ({ pixels }) => {
  const canvasRef = useRef(null)
  const [imageConverted, setImageConverted] = useState('')
  const layerArr = useLayerStore((state) => state.layerArr)

  useEffect(() => {
    let isCurrent = true

    const formatData = async () => {
      const mergedLayers = []

      for (const layer of layerArr) {
        const layerImages = await collectLayerImages(layer)
        mergedLayers.push(...layerImages)
      }

      if (!mergedLayers.length) {
        if (isCurrent) {
          setImageConverted('')
        }
        return
      }

      const mergedImage = await mergeImages(mergedLayers)
      if (isCurrent) {
        setImageConverted(mergedImage)
      }
    }

    formatData()

    return () => {
      isCurrent = false
    }
  }, [layerArr])

  useEffect(() => {
    const canvas = canvasRef.current
    const scaling = pixels / 35
    const width = canvas.width
    const context = canvas.getContext('2d')
    canvas.width = width
    if (!imageConverted) {
      return
    }
    const image = new Image()
    image.src = imageConverted
    image.onload = () => {
      context.imageSmoothingEnabled = false
      context.mozImageSmoothingEnabled = false
      context.oImageSmoothingEnabled = false
      context.webkitImageSmoothingEnabled = false
      context.scale(scaling, scaling)
      context.drawImage(image, 0, 0)
    }
  }, [imageConverted, pixels])

  return (
    <canvas id='canvas' ref={canvasRef} height={pixels} width={pixels}></canvas>
  )
}

export default Canvas
