import colors from './colors'
import SkinColors from './skinColors'

const assetContext = require.context('../assetsV3', true, /\.png$/)

const resolveAssetImport = (key) => {
  const importedAsset = assetContext(key)
  return importedAsset?.default || importedAsset
}

const primaryPaletteOptions = Array.from(
  new Set(
    colors
      .filter((colorObject) => colorObject.fileName.startsWith('primary_'))
      .map((colorObject) => colorObject.fileName)
  )
)

const skinPaletteOptions = SkinColors.map((colorObject) => colorObject.fileName)

const defaultTintSelection = primaryPaletteOptions.includes('primary_White.png')
  ? 'primary_White.png'
  : primaryPaletteOptions[0]

const defaultSkinSelection = skinPaletteOptions.includes('primary_Pale.png')
  ? 'primary_Pale.png'
  : skinPaletteOptions[0]

const rawAssets = {}
const rawBodyFiles = []

const numericFilePattern = /^\d+\.png$/i
const legacyPrimaryPattern = /^primary_/i
const legacySecondaryPattern = /^secondary_/i

const sortFileNames = (left, right) => {
  const leftIsNumeric = numericFilePattern.test(left)
  const rightIsNumeric = numericFilePattern.test(right)

  if (leftIsNumeric && rightIsNumeric) {
    return Number.parseInt(left, 10) - Number.parseInt(right, 10)
  }

  return left.localeCompare(right, undefined, {
    numeric: true,
    sensitivity: 'base',
  })
}

assetContext.keys().forEach((key) => {
  const normalizedKey = key.replace('./', '')
  const assetPath = resolveAssetImport(key)
  const pathSegments = normalizedKey.split('/')

  if (pathSegments.length === 2) {
    const [layerType, fileName] = pathSegments
    if (layerType === 'Body' && numericFilePattern.test(fileName)) {
      rawBodyFiles.push({ fileName, assetPath })
    }
    return
  }

  if (pathSegments.length !== 3) {
    return
  }

  const [layerType, assetName, fileName] = pathSegments

  if (!rawAssets[layerType]) {
    rawAssets[layerType] = {}
  }

  if (!rawAssets[layerType][assetName]) {
    rawAssets[layerType][assetName] = {}
  }

  rawAssets[layerType][assetName][fileName] = assetPath
})

const buildTintPartMeta = ({
  key,
  label,
  sourceFileName,
  sourcePath,
  colorOptions = primaryPaletteOptions,
  defaultSelection = defaultTintSelection,
  tintMode = 'luminance-map',
}) => ({
  key,
  label,
  type: 'tint',
  sourceFileName,
  sourcePath,
  colorOptions,
  defaultSelection,
  tintMode,
})

const buildNumberedLayers = (assetFiles, fileNames) =>
  fileNames.map((fileName) => {
    const partNumber = fileName.replace('.png', '')
    return buildTintPartMeta({
      key: partNumber,
      label: fileNames.length > 1 ? `Part ${partNumber}` : 'Color',
      sourceFileName: fileName,
      sourcePath: assetFiles[fileName],
    })
  })

const buildLegacySourceLayers = (assetFiles, fileNames) => {
  const groupedFiles = [
    fileNames.filter((fileName) => legacyPrimaryPattern.test(fileName)),
    fileNames.filter((fileName) => legacySecondaryPattern.test(fileName)),
  ].filter((group) => group.length > 0)

  return groupedFiles.map((group, index) => {
    const sourceFileName =
      group.find((fileName) => /white/i.test(fileName)) ||
      group.find((fileName) => !/none/i.test(fileName)) ||
      group[0]

    return buildTintPartMeta({
      key: `${index + 1}`,
      label: groupedFiles.length > 1 ? `Part ${index + 1}` : 'Color',
      sourceFileName,
      sourcePath: assetFiles[sourceFileName],
    })
  })
}

const buildStandaloneLayers = (assetFiles, fileNames) =>
  fileNames.map((fileName, index) =>
    buildTintPartMeta({
      key: `${index + 1}`,
      label: fileNames.length > 1 ? `Part ${index + 1}` : 'Color',
      sourceFileName: fileName,
      sourcePath: assetFiles[fileName],
    })
  )

const buildAssetMeta = (assetFiles) => {
  const fileNames = Object.keys(assetFiles).sort(sortFileNames)
  const previewPath = assetFiles['preview.png'] || null
  const numberedFiles = fileNames.filter((fileName) => numericFilePattern.test(fileName))
  const nonPreviewFiles = fileNames.filter((fileName) => fileName !== 'preview.png')
  const legacyNamedFiles = nonPreviewFiles.filter(
    (fileName) =>
      legacyPrimaryPattern.test(fileName) || legacySecondaryPattern.test(fileName)
  )
  const standaloneFiles = nonPreviewFiles.filter(
    (fileName) =>
      !numericFilePattern.test(fileName) &&
      !legacyPrimaryPattern.test(fileName) &&
      !legacySecondaryPattern.test(fileName)
  )

  let layers = []
  let structure = 'single'

  if (numberedFiles.length > 0) {
    layers = buildNumberedLayers(assetFiles, numberedFiles)
    structure = numberedFiles.length > 1 ? 'multipart' : 'single'
  } else if (legacyNamedFiles.length > 0) {
    layers = buildLegacySourceLayers(assetFiles, legacyNamedFiles)
    structure = layers.length > 1 ? 'multipart' : 'single'
  } else if (standaloneFiles.length > 0) {
    layers = buildStandaloneLayers(assetFiles, standaloneFiles)
    structure = standaloneFiles.length > 1 ? 'multipart' : 'single'
  }

  if (!layers.length) {
    return null
  }

  return {
    previewPath: previewPath || layers[0]?.sourcePath || null,
    structure,
    layers,
  }
}

const data = Object.keys(rawAssets)
  .sort((left, right) => left.localeCompare(right))
  .reduce((accumulator, layerType) => {
    const layerAssets = Object.keys(rawAssets[layerType])
      .sort((left, right) =>
        left.localeCompare(right, undefined, {
          numeric: true,
          sensitivity: 'base',
        })
      )
      .reduce((layerAccumulator, assetName) => {
        const assetMeta = buildAssetMeta(rawAssets[layerType][assetName])
        if (assetMeta) {
          layerAccumulator[assetName] = assetMeta
        }
        return layerAccumulator
      }, {})

    if (Object.keys(layerAssets).length > 0) {
      accumulator[layerType] = layerAssets
    }

    return accumulator
  }, {})

const bodyAssets = rawBodyFiles
  .sort((left, right) => sortFileNames(left.fileName, right.fileName))
  .reduce((accumulator, bodyFile) => {
    const partNumber = bodyFile.fileName.replace('.png', '')
    const assetName = `Body_${partNumber}`

    accumulator[assetName] = {
      previewPath: bodyFile.assetPath,
      structure: 'body',
      label: `Body ${partNumber}`,
      bodyPartNumber: Number.parseInt(partNumber, 10),
      layers: [
        buildTintPartMeta({
          key: 'body',
          label: 'Tone',
          sourceFileName: bodyFile.fileName,
          sourcePath: bodyFile.assetPath,
          colorOptions: skinPaletteOptions,
          defaultSelection: defaultSkinSelection,
        }),
      ],
    }

    return accumulator
  }, {})

const getLayerAssetMap = (layerType) => {
  if (layerType === 'Body') {
    return bodyAssets
  }

  return data[layerType] || {}
}

const getAssetMeta = (layerType, assetName) =>
  getLayerAssetMap(layerType)?.[assetName] || null

const getAssetPartMeta = (layerType, assetName, partKey) =>
  getAssetMeta(layerType, assetName)?.layers.find((layer) => layer.key === partKey) ||
  null

const getAssetPreviewPath = (layerType, assetName) =>
  getAssetMeta(layerType, assetName)?.previewPath || null

const getAssetImagePath = (layerType, assetName, partKey) =>
  getAssetPartMeta(layerType, assetName, partKey)?.sourcePath || null

const isEmptyColorSelection = (selection) => selection?.endsWith('None.png')

const bodyPartDefinitions = Object.keys(bodyAssets)
  .sort(
    (left, right) =>
      (bodyAssets[left]?.bodyPartNumber || 0) - (bodyAssets[right]?.bodyPartNumber || 0)
  )
  .map((assetName) => ({
    assetName,
    ...bodyAssets[assetName],
  }))

export {
  bodyAssets,
  bodyPartDefinitions,
  defaultSkinSelection,
  defaultTintSelection,
  getAssetImagePath,
  getAssetMeta,
  getAssetPartMeta,
  getAssetPreviewPath,
  getLayerAssetMap,
  isEmptyColorSelection,
  primaryPaletteOptions,
  skinPaletteOptions,
}

export default data
